# Generated by packaging/release.py for each release; edit the template, not this file.
class SystemSteward < Formula
  desc "{{DESCRIPTION}}"
  homepage "{{HOMEPAGE}}"
  url "{{SOURCE_URL}}"
  sha256 "{{SOURCE_SHA256}}"
  license "{{LICENSE}}"

  depends_on :macos
  depends_on "python@3.13"

{{RESOURCES}}

  def install
    python = Formula["python@3.13"].opt_bin/"python3.13"
    system python, "-m", "venv", libexec/"venv"

    # The pinned requirements are pure-Python wheels: install them offline, exactly as pinned.
    wheels = buildpath/"wheels"
    wheels.mkpath
    resources.each do |r|
      r.fetch
      cp r.cached_download, wheels/File.basename(r.url)
    end
    system libexec/"venv/bin/python", "-m", "pip", "install", "--no-deps", "--no-index",
           "--disable-pip-version-check", *Dir[wheels/"*.whl"]

    (libexec/"app").install Dir["*.py"], "tui", "platforms", "system_steward.tcss"
    (bin/"system-steward").write <<~SH
      #!/bin/bash
      exec "#{libexec}/venv/bin/python" "#{libexec}/app/system_steward.py" "$@"
    SH
    chmod 0755, bin/"system-steward"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/system-steward --version")
    assert_match "\"entries\"", shell_output("#{bin}/system-steward --json --timeout 5 #{testpath}")
  end
end
